def f(N, K):
	if N == 1:
		return 1.0
	if N == 2:
		return 0.5
	for i in range(K):
		if N == 1:
			break
		if N == 2:
			N = 1
		if i == 0:
			if N % 4 == 0:
				N //= 2
			else:
				N = N // 2 + 1
		elif N % 2 == 0:
			N //= 2
		else:
			N = N // 2 + 1
	return 1.0 / N
T = int(input())
for _ in range(T):
	(N, K) = (int(x) for x in input().split())
	print(f(N, K))
